def calc(a, b, op):
    if op == 0:
        return a + b
    if op == 1:
        return a - b
    if op == 2:
        return a * b
    if op == 3:
        return a / b
    return 0

print(calc(10, 5, 0))
print(calc(10, 5, 1))
print(calc(10, 5, 2))
print(calc(10, 5, 3))

def sign(x):
    if x > 0:
        return 1
    if x < 0:
        return -1
    return 0

def absolute(x):
    return -x if x < 0 else x

def maximum(a, b):
    return a if a > b else b

print(sign(5))
print(sign(-3))
print(sign(0))
print(absolute(-7))
print(maximum(3, 8))

def fizzbuzz(n):
    for i in range(1, n + 1):
        if i % 15 == 0:
            print("FizzBuzz")
        elif i % 3 == 0:
            print("Fizz")
        elif i % 5 == 0:
            print("Buzz")
        else:
            print(i)

fizzbuzz(15)

def countdown(n):
    for i in range(1, n + 1):
        print(n - i + 1)

def sumto(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def factorial(n):
    result = 1
    x = n
    while x > 1:
        result *= x
        x -= 1
    return result

countdown(5)
print(sumto(10))
print(factorial(5))

